# Preserve bilingual content and audio configuration when regenerating the English seed.
existing_seed_path=p/'src'/'seed.json'
if existing_seed_path.exists():
    existing_seed=json.loads(existing_seed_path.read_text())
    for extension in ('translations','audio'):
        if extension in existing_seed:
            seed[extension]=existing_seed[extension]
(p/'src'/'seed.json').write_text(json.dumps(seed,ensure_ascii=False,indent=2))
(p/'database'/'schema.sql').write_text('''-- D1 setup. Safe to run again: data is only seeded if missing.\nCREATE TABLE IF NOT EXISTS site_config (id TEXT PRIMARY KEY, body TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);\nCREATE TABLE IF NOT EXISTS content (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('news','social','achievement')), title TEXT NOT NULL, excerpt TEXT DEFAULT '', body TEXT DEFAULT '', image TEXT DEFAULT '', url TEXT DEFAULT '', platform TEXT DEFAULT '', media_type TEXT DEFAULT '', status TEXT NOT NULL CHECK(status IN ('draft','published')) DEFAULT 'draft', published_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, external_id TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);\nCREATE INDEX IF NOT EXISTS idx_content_status_kind ON content(status,kind,published_at DESC);\nCREATE TABLE IF NOT EXISTS newsletter_subscribers (email TEXT PRIMARY KEY, consent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, confirmed_at TEXT, confirm_hash TEXT, unsubscribe_hash TEXT NOT NULL, revoked_at TEXT, source TEXT NOT NULL DEFAULT 'website');\nCREATE INDEX IF NOT EXISTS idx_sub_confirm ON newsletter_subscribers(confirm_hash);\nCREATE INDEX IF NOT EXISTS idx_sub_unsub ON newsletter_subscribers(unsubscribe_hash);\nCREATE TABLE IF NOT EXISTS admin_audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);\nINSERT OR IGNORE INTO site_config (id,body) VALUES ('main', ''' + "'"+json.dumps(seed,ensure_ascii=False,separators=(',',':')).replace("'","''")+"'" + ''');\n''')
# Keep the initial bilingual translation table and seed article translations in fresh databases.
